<script setup lang="ts">
import type {Job} from '@career-launch/shared';import {formatDeadline} from '@career-launch/shared';import {StatusBadge} from '@career-launch/ui';import {onMounted,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {repository} from '../../services/repository'
const route=useRoute();const router=useRouter();const job=ref<Job|null>(null);const applying=ref(false);const applied=ref(false)
onMounted(async()=>{job.value=await repository.jobs.get(String(route.params.id))})
async function apply(){if(!job.value)return;applying.value=true;await repository.applications.start(job.value.id);applied.value=true;applying.value=false;window.open(job.value.applyUrl,'_blank','noopener,noreferrer')}
</script>
<template><section v-if="job" class="cl-page cl-container detail"><main><div class="detail-head"><span class="logo">{{job.companyLogoText}}</span><div><RouterLink :to="`/companies/${job.companyId}`">{{job.companyName}}</RouterLink><h1>{{job.title}}</h1><div class="meta"><span>{{job.city.join(' / ')}}</span><span>{{job.education.join(' / ')}}</span><span>{{job.category}}</span></div></div></div><div class="content cl-card"><h2>职位描述</h2><p>{{job.description}}</p><h2>任职要求</h2><ul><li v-for="item in job.requirements" :key="item">{{item}}</li></ul><h2>专业要求</h2><p>{{job.majors.join('、')}}</p></div></main><aside><div class="apply-box cl-card"><StatusBadge tone="warning">{{formatDeadline(job.deadlineAt)}}</StatusBadge><strong>{{job.salaryLabel}}</strong><button class="cl-primary-button" data-action="apply" :disabled="applying" @click="apply">{{applying?'正在记录…':'去官方投递'}}</button><p v-if="applied" role="status">已加入投递看板，完成网申后记得更新状态。</p><small>职位来源：{{job.sourceLabel}}<br/>更新于 {{new Date(job.updatedAt).toLocaleDateString('zh-CN')}}</small></div><button class="cl-quiet-button back" @click="router.back()">返回职位列表</button></aside></section><section v-else class="cl-page cl-container">正在加载职位信息…</section></template>
<style scoped>
.detail{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:22px}.detail-head{display:flex;gap:16px;margin-bottom:24px}.logo{width:58px;height:58px;display:grid;place-items:center;border-radius:14px;color:var(--cl-primary);background:var(--cl-primary-soft);font-size:22px;font-weight:800}.detail-head a{color:var(--cl-primary);font-weight:700}.detail-head h1{margin:2px 0 4px;color:var(--cl-text-strong);font-size:34px}.meta{display:flex;gap:18px;color:var(--cl-muted)}.content{padding:28px}.content h2{margin:28px 0 10px;font-size:19px}.content h2:first-child{margin-top:0}.content p,.content li{color:var(--cl-muted)}.apply-box{position:sticky;top:92px;display:grid;gap:14px;padding:22px}.apply-box>strong{color:var(--cl-text-strong);font-size:22px}.apply-box p{margin:0;color:var(--cl-success);font-size:13px}.apply-box small{padding-top:12px;border-top:1px solid var(--cl-border);color:var(--cl-muted)}.back{width:100%;margin-top:10px}@media(max-width:780px){.detail{grid-template-columns:1fr}.apply-box{position:static}.detail aside{grid-row:1}.detail-head h1{font-size:28px}}
</style>
